using System;
using System.Collections;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using Unity.Netcode;
using UnityEngine;
namespace Pinefall
{
    public sealed class LivingReserveProbe:MonoBehaviour
    {
        [Serializable]class Report{public List<string> passed=new List<string>(),failed=new List<string>(),errors=new List<string>();public int villages,houses,vehicles,animals;}
        Report report=new Report();void Awake(){Application.logMessageReceived+=Log;}void Log(string m,string stack,LogType type){if(type==LogType.Exception||type==LogType.Error)report.errors.Add(m+"\n"+stack);}void Check(bool value,string label){(value?report.passed:report.failed).Add(label);Debug.Log("LIVING_CHECK "+label+" "+value);Write();}void Write(){File.WriteAllText(ReserveSession.Arg("--report"),JsonUtility.ToJson(report,true));}
        IEnumerator Start()
        {
            var session=ReserveSession.Instance;float until=Time.realtimeSinceStartup+60;while(!Ranger.Local&&Time.realtimeSinceStartup<until)yield return null;if(!Ranger.Local){Check(false,"Host or client initialized");Application.Quit();yield break;}var p=Ranger.Local;
            if(!session.IsHost){until=Time.realtimeSinceStartup+65;while(!p.SurveyWarning&&Time.realtimeSinceStartup<until)yield return null;yield return new WaitForSecondsRealtime(1);Check(p.SurveyWarning,"Survey warns every connected player");Check(p.Team.Value==0?p.SurveyVisible&&p.SurveyPoints.Length==1:!p.SurveyVisible,"Only the activating team receives enemy position snapshots");yield return new WaitForSecondsRealtime(13);Check(!p.SurveyVisible&&!p.SurveyWarning,"Survey pings and exposure warning expire");Check(ProximityVoice.Current.MicrophoneStarts==0,"No microphone capture");Write();Application.Quit();yield break;}
            until=Time.realtimeSinceStartup+55;while(Ranger.Players.Count<3&&Time.realtimeSinceStartup<until)yield return null;Check(Ranger.Players.Count==3,"Three players connected to the expanded reserve");yield return new WaitForSecondsRealtime(1);
            report.villages=ExpeditionLayout.Regions.Length;report.houses=ExpeditionLayout.Regions.Sum(r=>ExpeditionLayout.HouseCount(r));report.vehicles=RoadVehicle.All.Count;report.animals=session.Animals.Count;
            Check(report.villages>=48&&report.houses>=200,"Forty-eight settlements contain more than two hundred searchable buildings");Check(report.vehicles>=80&&RoadVehicle.All.Count(v=>v.Type.Value==5)>=8&&RoadVehicle.All.Count(v=>v.Type.Value==4)>=10,"Distributed motorcycles, cars and launches populate travel routes");Check(report.animals>=190,"Denser procedural wildlife populations");Check(ReserveWater.Lakes.Length>=5&&ReserveWater.Depth(1500,750)>5,"New navigable lakes are carved into terrain");Check(ReserveBiomes.Label(1000,850)=="Amberwood floodplain","Autumn floodplain has its own habitat label");
            bool audio=true;foreach(string bank in new[]{"grass","gravel","sand","snow","wood","rifle","carbine","shotgun","pistol","smg","support","pig","canid","goat","elk","reload"})audio&=Soundscape.HasBank(bank);Check(audio,"All recorded surface, weapon and wildlife sound banks load");Check(GameBindings.Actions.Contains("Survey")&&GameBindings.Key("Survey")!=KeyCode.None,"Survey control can be rebound");
            yield return new WaitForSecondsRealtime(1.5f);Check(WildfrontMatch.Current.TransportPins.Length>=80,"Full-map transport registry includes vehicles beyond local render range");var mapCar=RoadVehicle.All.First(v=>v.Type.Value!=4);var original=mapCar.transform.position;var moved=ReserveWorld.OnGround(original.x+12,original.z,.65f);mapCar.transform.position=moved;yield return new WaitForSecondsRealtime(1.5f);var pin=WildfrontMatch.Current.TransportPins.FirstOrDefault(v=>v.id==mapCar.NetworkObjectId);Check(Vector3.Distance(pin.position,mapCar.transform.position)<2,"Vehicle map icons follow updated server positions");var rival=Ranger.Players.First(q=>q.Team.Value!=p.Team.Value);rival.ResetRound(mapCar.transform.position+Vector3.right);float moveDeadline=Time.realtimeSinceStartup+6;while(Vector3.Distance(rival.transform.position,mapCar.transform.position)>4&&Time.realtimeSinceStartup<moveDeadline)yield return null;mapCar.Condition.Value=100;bool rivalEntered=mapCar.Enter(rival);Check(rivalEntered,"Rival enters the vehicle before visibility is checked");yield return new WaitForSecondsRealtime(1.5f);Check(!WildfrontMatch.Current.TransportPins.Any(v=>v.id==mapCar.NetworkObjectId)&&!WildfrontMatch.VisibleTransport(mapCar,p.Team.Value),"Enemy-occupied vehicles do not reveal rivals on the map");mapCar.Remove(rival);
            int churnErrors=report.errors.Count;var transient=ExpeditionLoot.Spawn(ReserveWorld.OnGround(-2800,-2800,.4f),5,0,0,1);foreach(var client in session.Network.ConnectedClientsIds)if(client!=NetworkManager.ServerClientId&&!transient.NetworkObject.IsNetworkVisibleTo(client))transient.NetworkObject.NetworkShow(client);transient.NetworkObject.Despawn();yield return new WaitForSecondsRealtime(.3f);Check(report.errors.Count==churnErrors&&Ranger.Players.Count==3,"Objects shown and removed in one network tick leave no stale spawn queue");
            p.Hunger.Value=19;Check(!p.CanSprint&&p.HungerStatus.Contains("sprint"),"Low hunger explicitly locks sprinting");p.Food.Value=1;p.EatServerRpc();Check(p.CanSprint&&p.Hunger.Value>=54&&p.Food.Value==0,"Eating restores sprint eligibility and consumes carried food");yield return null;
            p.SurveyCharges.Value=1;var enemy=Ranger.Players.FirstOrDefault(q=>q.Team.Value!=p.Team.Value);p.SurveyServerRpc();yield return new WaitForSecondsRealtime(1);Check(p.SurveyCharges.Value==0&&p.SurveyVisible&&p.SurveyPoints.Length==1&&enemy&&Vector3.Distance(p.SurveyPoints[0],enemy.transform.position)<5,"Survey consumes one charge and reveals enemy snapshots to its team");p.SurveyCharges.Value=1;p.SurveyServerRpc();yield return null;Check(p.SurveyCharges.Value==1,"An active scan cannot waste a second charge");
            yield return new WaitForSecondsRealtime(12);Check(!p.SurveyVisible&&!p.SurveyWarning,"Server timed scan expires after twelve seconds");p.SurveyCharges.Value=1;int before=WorldLoot.All.Count(l=>l.Kind.Value==12);p.DropItemServerRpc(12,0,1);yield return null;var dropped=WorldLoot.All.FirstOrDefault(l=>l.Kind.Value==12);Check(p.SurveyCharges.Value==0&&WorldLoot.All.Count(l=>l.Kind.Value==12)==before+1,"Survey tool can be dropped for other players");if(dropped)p.ScavengeServerRpc(dropped.NetworkObjectId);yield return null;Check(p.SurveyCharges.Value==1,"Dropped survey tool can be collected");
            int bikes=RoadVehicle.All.Count(v=>v.Type.Value==5);bool released=SupplySpecials.Release(ReserveWorld.OnGround(0,-230),1);yield return null;Check(released&&RoadVehicle.All.Count(v=>v.Type.Value==5)==bikes+1,"A special supply reward creates a usable motorcycle on dry ground");var bike=RoadVehicle.All.Last(v=>v.Type.Value==5);p.SmokeMoveTo(bike.transform.position+Vector3.right);Check(bike.Enter(p)&&p.CurrentVehicle==bike&&bike.Capacity==2,"Motorcycle supports entering the driver seat");bike.Remove(p);
            int beacons=WorldLoot.All.Count(l=>l.Kind.Value==12);SupplySpecials.Release(ReserveWorld.OnGround(0,-225),2);Check(WorldLoot.All.Count(l=>l.Kind.Value==12)==beacons+1,"Supply crates can release a survey beacon");
            Check(ProximityVoice.Current.MicrophoneStarts==0,"Verification never records the microphone");Write();yield return new WaitForSecondsRealtime(4);Application.Quit();
        }
        void OnDestroy(){Application.logMessageReceived-=Log;}
    }
}
